\label{THM}
Let $M$ be a smooth manifold equipped with a complete sub-Riemannian structure $(\Delta,g)$ and $x\in M$ be fixed. If for almost every $y\in M$ all minimizing horizontal paths from $x$ to $y$ have Goh-rank at most $1$, then the closed set $\Abn^{\min}(x)$ has Lebesgue measure zero in $M$.
\end{theorem}

\label{COR1}
Let $M$ be a smooth manifold equipped with a complete sub-Riemannian structure $(\Delta,g)$ having minimizing co-rank $1$ almost everywhere. Then the Minimizing Sard Conjecture is satisfied.
\end{corollary}

\label{COR2}
Let $M$ be a smooth manifold equipped with a complete sub-Riemannian structure $(\Delta,g)$ with $\Delta$ pre-medium-fat almost everywhere. Then the Minimizing Sard Conjecture is satisfied.
\end{corollary}

\label{COR3}
Let $M$ be a smooth manifold equipped with a complete sub-Riemannian structure $(\Delta,g)$ of rank $m\geq 2$ where $\Delta$ is generic in the set of smooth totally nonholonomic distributions of rank $m$ over $M$. Then the Minimizing Sard Conjecture is satisfied.
\end{corollary}

\label{PROPnonemptydense}
The set of $x\in \mathcal{O}$ such that $\partial^-f(x)\neq \emptyset$ is a dense subset of $\mathcal{O}$.
\end{proposition}

\label{PROPidem}
For every $x\in \mathcal{O}$, every $p\in \partial^-f(x)$ and every neighborhood $\mathcal{W}$ of $(x,p)$ in $T^*M$, there is $y \in \mathcal{O}$ and $q\in \partial^-_P f(y)$ such that $(y,q)\in \mathcal{W}$.
\end{proposition}

\label{LEMSubbotin}
Let $h:O \to \R$ be a continuous function on an open set $O\subset \R^n$, $x\in \R^n$, and let $\rho \in \R$ be such that
\[
Dh(x;v) := \lim_{\substack{w\to v\\ t\downarrow 0}} \frac{h(x+tw)-h(x)}{t} > \rho \qquad \forall v \in \bar{B}_1,
\]
where $\bar{B}_1$ stands for the closed unit ball in $\R^n$. Then, for any $\epsilon >0$, there exist $z\in B_{\epsilon}(x)$ and $\zeta \in \partial^-_Ph(z)$ such that
\begin{equation*}
|f(z)-f(x)| < \epsilon \quad
\text{and} \quad \zeta \cdot v > \rho \qquad \forall v \in \bar{B}_1.
\end{equation*}
\end{lemma}

\label{PROPSubLip}
Let $\mathcal{C} \subset \mathcal{O}$ be an open convex set (with respect to $h$) and $K\geq 0$ be fixed, then the following properties are equivalent:
\begin{enumeratei}
\item\label{PROPSubLipi}
$f$ is $K$-Lipschitz (with respect to $d^h$) on $\mathcal{C}$.
\item\label{PROPSubLipii}
For every $x\in \mathcal{C}$ and every $p\in \partial^-f(x)$, $|p|_x\leq K$.
\end{enumeratei}
\end{proposition}

\label{PROPSubLipEQ}
For every $x\in \mathcal{O}$, the following properties are equivalent:
\begin{enumeratei}
\item
$x \in \Lip\,(f)$.
\item
$\partial^-f$ is bounded in a neighborhood of $x$, that is, there is a neighborhood $\mathcal{V}\subset \mathcal{O}$ of $x$ such that the set of $(y,q)$ with $y\in \mathcal{V}, q\in \partial^-f(y)$ is relatively compact in $T^*M$.
\end{enumeratei}
\end{proposition}

\label{PROPLip-Lim}
Let $h$ be a smooth Riemannian metric on $M$, $K>0$ and $x\in \mathcal{O}$ be such that $f$ admits a support function from below at $x\in M$ which is $K$-Lipschitz (with respect to $d^h$) on its domain, then there is $p\in \partial^-_Lf(x)$ with $|p|_x\leq K$.
\end{proposition}

\label{PROPLip-Sub}
There is a set $\mathcal{N}\subset \Lip^-(f)$ of Lebesgue measure zero in $M$ such that $\partial^-f(x)\neq \emptyset$ for every $x\in \Lip^-(f) \setminus \mathcal{N}$.
\end{proposition}

\label{PROPDichotomy}
Let $a,b\in \R$ with $a<b$ and $\varphi :(a,b) \to \R$ be a continuous function. Then, for almost every $x\in (a,b)$, at least one of the following properties is satisfied:
\begin{enumeratei}
\item\label{PROPDichotomyi}
$\varphi$ is differentiable at $x$.
\item\label{PROPDichotomyii}
There is a sequence $\{x_k\}_{k\in \N}$ converging to $x$ such that $0\in \partial^-\varphi(x_k)$ for all $k\in \N$, in particular we have $0\in \partial^-_L \varphi(x)$.
\end{enumeratei}
\end{proposition}

\label{RemDYS}
The Denjoy-Young-Saks Theorem allows to make more precise assertion \eqref{PROPDichotomyii}. Given $\varphi$ as in Proposition \ref{PROPDichotomy}, the {\it Dini derivatives} $D^+\varphi, D_+\varphi,D^-\varphi, D_-\varphi:(a,b) \to \R\cup \{\pm \infty\}$ of $\varphi$ at $x\in (a,b)$ are defined by
\begin{align*}
D^+\varphi(x) &= \limsup_{h\to 0^+} \frac{\varphi(x+h)-\varphi(x)}{h}, & D_+\varphi(x) &= \liminf_{h\to 0^+} \frac{\varphi(x+h)-\varphi(x)}{h},
\\
D_-\varphi(x) &= \liminf_{h\to 0^+} \frac{\varphi(x)-\varphi(x-h)}{h}, & D^-\varphi(x) &= \limsup_{h\to 0^+} \frac{\varphi(x)-\varphi(x-h)}{h}.
\end{align*}
Denjoy-Young-Saks' Theorem (see \cite{hanson34} and references therein) asserts that for almost every $x\in (a,b)$, one of the following assertions holds:
\begin{enumerate}
\item\label{DYS1}
$D^+\varphi(x)= D_+\varphi(x)=D^-\varphi(x)= D_-\varphi(x) \in \R$, \ie $f$ is differentiable at $x$,
\item\label{DYS2}
$D^+f(x)=D^-f(x)=+\infty$ and $D_+f(x)=D_-f(x)=-\infty$,
\item\label{DYS3}
$D^+f(x)=+\infty, D_-f(x)=-\infty$ and $D_+f(x)=D^-f(x)\in \R$,
\item\label{DYS4}
$D^-f(x)=+\infty, D_+f(x)=-\infty$ and $D_-f(x)=D^+f(x)\in \R$.
\end{enumerate}
As a consequence, we may also suppose in Proposition \ref{PROPDichotomy}\eqref{PROPDichotomyii} that one of the above assertions \eqref{DYS2}, \eqref{DYS3}, \eqref{DYS4} is satisfied.
\end{remark}

\label{PROPLip-PL}
For every $x\in \mathcal{O}$, $\partial^-_{PL}f(x)=\emptyset$ if and only if $x\in \Lip(f)$.
\end{proposition}

\label{PROPp0}
Depending on the value of $\bar{p}_0^u \in \{0,1\}$ in (\ref{Lagrange}), we have:
\begin{enumeratei}
\item\label{PROPp0i}
If $\bar{p}_0^u=0$, then $\psi^{u,\bar{p}^u}$ is an abnormal extremal (and $\gamma^{u}$ is a singular).
\item\label{PROPp0ii}
If $\bar{p}_0^u=1$, then $\psi^{u,\bar{p}^u}$ is a normal extremal and we have
\[
u(t) = B^u(t)^{*} p(t)^* \qquad \text{for a.e. } t \in [0,1].
\]
\end{enumeratei}
\end{proposition}

\label{PROPsub1}
Let $y\in M\setminus \{x\}$, $p\in \partial^- f_x(y)$ and $u\in U$ be a local minimizer of $C$ with end-point $E(u)=y$, then we have
\begin{equation}\label{26sept1}
p\cdot D_{u}E = D_{u}C.
\end{equation}
In particular, there is a unique minimizing geodesic from $x$ to $y$, it is given by the projection of the normal extremal $\psi:[0,1] \to T^*M$ satisfying $\psi(1)=(y,p)$. Moreover, if $\psi(0)$ is not a critical point of the exponential mapping $\exp_x$, then $y$ does not belong to $\Abn^{\min}(x)$.
\end{proposition}

\label{REM28oct}
We note that if $y\in M\setminus \{x\}$, $p\in \partial^-_P f_x(y)$ and $u\in U$ is a local minimizer of $C$ with end-point $E(u)=y$, then we have (\ref{26sept1}) and moreover since the function $C-\varphi\circ E$ with a local minimum at $u$ is of class $C^2$ (where $\varphi:M\to \R$ is a support function from below of class $C^2$ with $d\varphi(x)=p$), we have
\begin{equation*}
D^2_uC (v) - p\cdot D^2_uE(v) \geq 0 \qquad \forall v \in \Ker(D_uE),
\end{equation*}
where $D^2_uC$ and $D^2_uE$ stand for the quadratic forms defined respectively by the second order differentials of $C$ and $E$ at $u$.
\end{remark}

\label{PROPsub2}
Let $y\in M\setminus \{x\}$ and $p\in \partial^-_L f_x(y)$, then the projection of the normal extremal $\psi:[0,1] \to T^*M$ satisfying $\psi(1)=(y,p)$ is a minimizing geodesic from $x$ to $y$.
\end{proposition}

\label{PROPGohNormal}
Assume that $\|\bar{u}\|_{L^{\infty}}<L$ for some $L>0$. Then for every $\kappa>0$ and every $N\in \N$, there are $\rho, \Lambda>0$ such that the following property is satisfied: For every $u\in U$ such that
\begin{equation}\label{HypGohNormal1}
\left\|u-\bar{u}\right\|_{L^2}< \rho, \quad \left\|u\right\|_{L^{\infty}}< 2L,
\end{equation}
and every $\bar{p}^u \in T_y^*M$ and $\bar{p}_0^u \in \R$, with $y:=E(u)$ and $(\bar{p}^u,\bar{p}_0^u) \neq (0,0)$, satisfying
\begin{equation}\label{Lagrange2}
\bar{p}^u \cdot D_{u} E = \bar{p}_0^u \, D_{u} C,
\end{equation}
together with
\begin{equation}\label{HypGohNormal2}
\left| \bar{p}^u\right|_y \geq \Lambda \, \left| \bar{p}_0^{u}\right|
\end{equation}
and
\begin{equation}\label{HypGohNormal3}
\mathrm{ind}_- \left(\left(\bar{p}^u,-\bar{p}_0^u\right) \cdot \left(D^2_{u} F \right)_{\vert \Ker (D_{u}F)} \right) < N,
\end{equation}
the extremal $\psi^{u,\bar{p}^u} = (\gamma^u(t),p^{u,\bar{p}^u}(t)): [0,1] \to T^*M$ defined by (\ref{formulaextremal}) satisfies
\begin{equation}\label{AlmostGoh}
\left| p^{u,\bar{p}^u}(t) \cdot \left[ X^i,X^j\right] \left(\gamma^u(t)\right)\right| \leq \kappa \left| \bar{p}^u\right|_y \qquad \forall t \in [0,1], \, \forall i,j = 1, \ldots, m.
\end{equation}
\end{proposition}

\label{LEM8sept}
There are $\rho, K>0$ such that for any $u\in U$ with $\|u-\bar{u}\|_{L^2}< \rho$, $\|u\|_{L^{\infty}}< 2L$ and any $\bar{t}, \delta>0$ with $[\bar{t},\bar{t}+\delta]\subset [0,1]$, the following property holds: For every $v\in \Ker (D_{u} E)$ with $\Supp (v)\in [\bar{t},\bar{t}+\delta]$ and every $\bar{p}^u\in T_y^*M$, we have
\begin{equation}\label{8sept3}
\left| \bar{p}^u \cdot D_{u}^2 E (v) - Q^{u,\bar{p}^u}_{\bar{t},\delta} (v) \right| \leq K \, \|v\|_{L^2}^2 \, \left|\bar{p}^u\right|_{y} \, \delta^2,
\end{equation}
where $Q^{u,\bar{p}^u}_{\bar{t},\delta}: L^2 \left([0,1],\R^m\right) \to \R^n$ is the quadratic form defined by
\begin{equation}\label{8septQ}
Q^{u,\bar{p}^u}_{\bar{t},\delta}(v) := \int_{\bar{t}}^{\bar{t}+\delta} \int_{\bar{t}}^t \langle v(s), M_{\bar{t}}^{u,\bar{p}^u}v(t)\rangle \, ds \, dt \qquad \forall v\in L^2 \left([0,1],\R^m\right)
\end{equation}
with
\begin{equation}\label{27avril1}
\bigl(M_{\bar{t}}^{u,\bar{p}^u}\bigr)_{i,j} = 2 \, p^{u,\bar{p}^u} (\bar{t}) \cdot D_{\gamma^u(\bar{t})} X^i \left(X^j\bigl(\gamma^u(\bar{t}) \bigr)\right) \qquad \forall i,j =1, \ldots,m.
\end{equation}
\end{lemma}

\label{20oct1}
We note that in the case where $u=\bar{u}$ and $\bar{p}_0^u=0$, Proposition \ref{PROPGohNormal} asserts that if we have
\begin{equation*}
\mathrm{ind}_- \left(\bar{p}^{\bar{u}} \cdot \left(D^2_{\bar{u}} E \right)_{\vert \Ker (D_{\bar{u}}E)} \right) < +\infty
\end{equation*}
for some $ \bar{p}^{\bar{u}}\neq 0$ such that $\bar{p}^{\bar{u}} \cdot D_{\bar{u}} E =0$, that is $\bar{p}^{\bar{u}}\in \Im(D_{\bar{u}}E)^{\perp}$, then the corresponding abnormal extremal $\psi^{\bar{u},\bar{p}^{\bar{u}}}$ satisfies the Goh condition. This is the classical Goh Condition for Abnormal Geodesics due to Agrachev and Sarychev, see \cite[Prop.\,3.6, p.\,389]{as99} and \cite[Th.\,2.20, p.\,61]{riffordbook}.
\end{remark}

\label{PROPSTEP1}
If $\Abn^{\min}(x)$ has positive Lebesgue measure in $M$, then there are a complete sub-Riemannian structure $(\bar{\Delta},\bar{g})$ of rank $m$ on $B_1(0)$ generated by an orthonormal family of smooth vector fields $\bar{\mathcal{F}}=\{\bar{X}^1, \ldots, \bar{X}^m\}$ on $B_1(0)$ along with a point $\bar{y} \in B_1(0)\setminus \{0\}$ such that the following properties are satisfied:
\begin{enumeratei}
\item
all minimizing horizontal paths from $0$ to $\bar{y}$ have Goh-rank at most $1$,
\item
$\bar{y}$ is a Lebesgue density point of $\Abn^{\min}(0)$.
\end{enumeratei}
\end{proposition}

\label{STEP1_LEM1}
For every compact set $\mathcal{K}\subset M$, the set of $\gamma \in \Gamma^y$ with $y\in \mathcal{K}$ is a compact subset of $W^{1,2}([0,1],M)$ and the mapping $y\in M \mto \Gamma^y \in \mathcal{C}(W^{1,2}([0,1],M))$ has closed graph (here $\mathcal{C}(W^{1,2}([0,1],M))$ stands for the set of compact subsets of $W^{1,2}([0,1],M)$ equipped with the Hausdorff topology).
\end{lemma}

\label{STEP1_LEM2}
There are an open neighborhood $\mathcal{B}$ of $\bar{y}$, a positive integer $N$, $N$~minimizing geodesics $\bar{\gamma}^1, \ldots$, $\bar{\gamma}^N \in \Gamma^{\bar{y}}$, $N$ open sets $\mathcal{V}^1, \ldots, \mathcal{V}^N \subset M$ diffeomorphic to $B_1(0)$ containing respectively $\bar{\gamma}^1([0,1]), \ldots, \bar{\gamma}^N([0,1])$, $N$ orthonormal families of smooth vector fields $\mathcal{F}^1 = \{X^{1,1}, \ldots, X^{1,m}\}, \ldots, \mathcal{F}^N = \{X^{N,1}, \ldots, X^{N,m}\}$ defined respectively on $\mathcal{V}^1, \ldots, \mathcal{V}^N$ and $N$ open sets $\mathcal{W}^1, \ldots, \mathcal{W}^N$ containing $\mathcal{B}$ with
\[
\bar{\gamma}^1([0,1]) \subset \overline{\mathcal{W}}^1 \subset \mathcal{V}^1, \ldots, \bar{\gamma}^N([0,1]) \subset \overline{\mathcal{W}}^N \subset \mathcal{V}^N
\]
such that the following properties are satisfied:
\begin{enumeratei}
\item\label{STEP1_LEM2i}
For every $k=1, \ldots, N$ and every $z\in \mathcal{V}^k$, $\Delta(z) = \Span\{X^{k,1}(z), \ldots, X^{k,m}(z)\}$.
\item\label{STEP1_LEM2ii}
For every $y\in \mathcal{B}$ and every $\gamma \in \Gamma^y$, there is $k_{\gamma} \in \{1, \ldots,N\}$ such that
\[
\gamma([0,1]) \subset \mathcal{W}^{k_{\gamma}}.
\]
\end{enumeratei}
\end{lemma}

\label{STEP1_LEM3}
For every $k=1, \ldots,N$, there is a smooth function $\psi^k : \mathcal{V}^k \to [1,+\infty)$ satisfying the following properties:
\begin{enumeratei}
\item\label{STEP1_LEM3i}
$\psi^k(z)=1$ for all $z\in \mathcal{W}^k$.
\item\label{STEP1_LEM3ii}
$\psi^k(z)>1$ for all $z\in \mathcal{V}^k \setminus \overline{\mathcal{W}}^k$.
\item\label{STEP1_LEM3iii}
The sub-Riemannian structure $(\Delta,g^k:=\psi^k g)$ on $\mathcal{V}^k$ is complete.
\end{enumeratei}
\end{lemma}

\label{PROPSTEP2}
There are $\delta, r, \rho \in (0,1)$, $K>0$, a control $\hat{u}$ in $U$ with $\gamma^{\hat{u}}\in \Gamma^{\hat{y}}$, a linear hyperplane $V\subset \R^n$ and a smooth function $h:[0,\delta^2/4) \to [0,+\infty)$ such that the following properties are satisfied:
\begin{enumeratei}
\item\label{PROPSTEP2i}
For every $u\in U$ with $\|u-\hat{u}\|_{L^2} < \delta$ and every $z\in V(\gamma^u(1)) \cap B_{\rho}(\gamma^u(1))$, there is $v \in U$ such that
\begin{gather}\label{PROPSTEP2_1}
\Proj_{V(\gamma^u(1))}^{\perp} \left(\gamma^{v}(1)\right)=z,
\\
\label{PROPSTEP2_2}
\left| \gamma^v(1)-z \right| \leq K | z-\gamma^u(1)|,
\\
\label{PROPSTEP2_3}
C(v) \leq C(u) + K \left|z - \gamma^u(1)\right|,
\\
\label{PROPSTEP2_4}
\left| \| v-\hat{u}\|_{L^2}^2 - \| u-\hat{u}\|_{L^2}^2 \right| \leq K | z-\gamma^u(1)|.
\end{gather}
\item\label{PROPSTEP2ii}
The function $h$ is smooth, nondecreasing and satisfies
\[
h(\alpha) = 0 \, \, \forall \alpha \in [0,\delta^2/4], \quad h(\alpha) > 0 \, \,\forall \alpha \in (\delta^2/4,\delta^2), \quad \lim_{\alpha \to \delta^2} h(\alpha)= +\infty.
\]
\item\label{PROPSTEP2iii}
The function $W: B_r(\hat{y}) \to [0,+\infty)$ defined by
\[
W(y) := \inf \bigl\{ C(u) + h\left(\|u-\hat{u}\|_{L^2}^2\right) \sep  u \in U \text{ s.t. } \gamma^{u}(1)=y \bigr\} \qquad \forall y \in B_r(\hat{y}) 
\]
is continuous and the set
\[
\mathcal{K} := \bigl\{y\in B_{r/2}(\hat{y})\setminus \Lip^-(W)\sep  W(y)=F(y) \bigr\}
\]
have positive Lebesgue measure.
\end{enumerat

\label{STEP2_LEM1}
For every $\gamma \in \Gamma^{\hat{y}}$, one of the following situation occurs:
\begin{enumeratei}
\item\label{STEP2_LEM1i}
$\gamma$ is not a singular horizontal path.
\item\label{STEP2_LEM1ii}
$\gamma$ is a singular horizontal path and $\Gohrank(\gamma)=1$.
\end{enumeratei}
\end{lemma}

\label{STEP2_LEM2}
Let $u \in U$ with $\gamma^u \in \Gamma^{\hat{y}}$ and $\gamma^u$ non-singular be fixed. Then there are $\delta, \rho \in (0,1)$ and $K>0$ such that the following property is satisfied: For every $v\in U$ with $\|v-u\|_{L^2} < \delta$ and every $z\in B_{\rho}(\gamma^v(1))$, there is $w \in U$ such that
\begin{gather}\label{STEP2_LEM2_1}
\gamma^w(1) =z,
\\
\label{STEP2_LEM2_2}
C(w) \leq C(v) + K |z-\gamma^v(1)|,
\\
\label{STEP2_LEM2_3}
\| w-v\|_{L^2} \leq K |z - \gamma^v(1)|,
\end{gather}
where the last inequality implies
\begin{equation}\label{STEP2_LEM2_4}
\bigl|\| w-u\|_{L^2}^2 - \| v-u\|_{L^2}^2\bigr| \leq K(K+2) | z-\gamma^v(1)|.
\end{equation}
\end{lemma}

\label{STEP2_LEM3}
Let $u \in U$ with $\gamma^u \in \Gamma^{\hat{y}}$ and $\gamma^u$ singular of Goh-rank $1$, be fixed. Then there are $\delta, \rho \in (0,1)$ and $K>0$ such that the following properties are satisfied: For~every $v\in U$ with $\|v-u\|_{L^2} < \delta$ and every $z\in V^{u}(\gamma^v(1)) \cap B_{\rho}(\gamma^v(1))$, there is $w \in U$ such that
\begin{gather}\label{STEP2_LEM3_1}
\Proj_{V^{u}(\gamma^v(1))}^{\perp} \left(\gamma^{w}(1)\right)=z,
\\
\label{STEP2_LEM3_2}
\left| \gamma^w(1)-z \right| \leq K \left| z-\gamma^v(1)\right|,
\\
\label{STEP2_LEM3_3}
C(w) \leq C(v) + K \left|z - \gamma^v(1)\right|,
\\
\label{STEP2_LEM3_4}
\left|\| w-u\|_{L^2}^2 - \| v-u\|_{L^2}^2\right| \leq K \left| z-\gamma^v(1)\right|.
\end{gather}
\end{lemma}

\label{STEP2_LEM4}
There are $\delta, r , \rho \in (0,1)$, $K>0$, a positive integer $N$, $N$ controls $u^1, \ldots, u^{N}$ in $U$ with $\gamma^{u^l}\in \Gamma^{\hat{y}}$ for $l=1, \ldots, N$ and $N$ linear hyperplanes $V^{u^1}, \ldots V^{u^{N}}$ in $\R^n$ such that the following properties are satisfied:
\begin{enumeratei}
\item\label{STEP2_LEM4i}
For every $l\in \{1, \ldots N\}$, every $v\in U$ with $\|v-u^l\|_{L^2} < \delta$ and every $z\in V^{u^l}(\gamma^v(1)) \cap B_{\rho}(\gamma^v(1))$, there is $w \in U$ such that
\begin{gather}\label{24oct1}
\Proj_{V^{u^l}(\gamma^v(1))}^{\perp} \left(\gamma^{w}(1)\right)=z,
\\
\label{24oct1bis}
\left| \gamma^w(1)-z \right| \leq K \left| z-\gamma^v(1)\right|,
\\
\label{24oct2}
C(w) \leq C(v) + K \left|z - \gamma^v(1)\right|,
\\
\label{24oct3}
\left| \| w-u^l\|_{L^2}^2 - \| v-u^l\|_{L^2}^2 \right| \leq K \left| z-\gamma^v(1)\right|.
\end{gather}
\item\label{STEP2_LEM4ii}
For any $y \in B_r(\hat{y})$ and $v \in \Gamma^y$, there is $l\in \{1, \ldots, N\}$, such that $\|v-u^l\|_{L^2} < \delta/2$.
\end{enumeratei}
\end{lemma}

\label{PROPSTEP3}
There exists $\check{K}>0$ such that for every $a\in B_{r/2}(\hat{y})\cap V(\hat{y})$ and every $\check{y} \in P_a$ the following property is satisfied: If $W_{|P_a}$ admits a support function from below $\varphi$ at $\check{y}$ which is Lipschitz on its domain (with Lipschitz constant $\Lip(\varphi)$), then there is $\nu>0$ such that
\[
W(y) \geq W(\check{y}) - \check{K} \left(1+\Lip(\varphi)\right) \left|y-\check{y}\right| \qquad \forall y \in B_{\nu}(\check{y});
\]
in particular, $\check{y}$ belongs to $\Lip^-(W)$.
\end{proposition}

\label{PROPSTEP4}
There are $\mu, \sigma >0$ with $B_{\mu}(\check{y}) \subset B_{r/2}(\hat{y})$ such that the following properties are satisfied:
\begin{enumeratei}
\item\label{PROPSTEP4i}
For any $t\in (-\mu,\mu)$ and any $p \in \partial^-W^{\check{a}}(t)$, there holds
\begin{equation*}
|p| \leq 1 \implies \Bigl(W^{\check{a}}(s) \leq W^{\check{a}}(t) + p (s-t)+\sigma (s-t)^2 \quad \forall s \in (-\mu,\mu)\Bigr).
\end{equation*}
\item\label{PROPSTEP4ii}
$D^-W^{\check{a}}(0)=+\infty, D_+W^{\check{a}}(0)=-\infty$ and $D_-W^{\check{a}}(0)=D^+W^{\check{a}}(0)\in \R$.
\end{enumeratei}
\end{proposition}

\label{STEP4_LEM1}
For every compact set $\mathcal{K}\subset B_{r/2}(\hat{y})$, the set of controls $u \in \Gamma^y_W$ with $y\in \mathcal{K}$ is a compact subset of $L^{2}([0,1],\R^m)$ and the mapping $y\in B_{r/2}(\hat{y}) \mto \Gamma^y_W \in \mathcal{C}(L^{2}([0,1],\R^m))$ has closed graph (here $\mathcal{C}(L^{2}([0,1],\R^m))$ stands for the set of compact subsets of $L^{2}([0,1],\R^m)$ equipped with the Hausdorff topology).
\end{lemma}

\label{PROPSTEP5}
Let $\epsilon, \sigma>0$, $a,b \in \R$ with $b>a$ be such that
\begin{equation}\label{9dec0}
\epsilon \geq \frac{(b-a)\sigma}{4}
\end{equation}
and let $h:[a,b]\to \R$ with $h(a)=h(b)=0$ be a continuous function such that for any $s\in (a,b)$ and $p\in \partial^-h(s)$ there holds
\begin{equation}\label{9dec1}
|p| \leq \epsilon \implies \Bigl(h(s') \leq h(s) + p (s'-s)+\sigma (s'-s)^2 \quad \forall s \in [a,b]\Bigr).
\end{equation}
Then we have
\begin{equation}\label{9dec2}
h(s) \geq D(s):= \max\bigl\{-\epsilon (s-a), \epsilon (s-b)\bigr\} \qquad \forall s \in [a,b].
\end{equation}
\end{proposition}

\label{THMopenquant}
Let $F: U \to \R^N$ be a mapping of class $C^2$ on an open set $U \subset X$, $\bar{u} \in U$ be a critical point of $F$ of co-rank $r$ and let $G :U \to \R^d$, with $d\in \N^*$, be a mapping of class $C^1$ on $U$. If there holds
\begin{equation}\label{ind}
\mathrm{ind}_- \Bigl(\lambda \cdot \left(D^2_{\bar{u}} F \right)_{\vert \Ker (D_{\bar{u}} F)} \Bigr) \geq N +d \qquad \forall \lambda \in \left(\Im \bigl(D_{\bar{u}} F \bigr)\right)^{\perp} \setminus \{0\},
\end{equation}
then there exist $(\delta, \rho) \in (0,1)$ and $K>0$ such that the following property holds: For every $u \in U$, $x\in \R^N$ with
\[
\| u - \bar{u}\| < \delta \quad \text{and} \quad |x-F(u)|<\rho,
\]
there are $w_1, w_2 \in X$ such that $u+w_1+w_2 \in U$,
\begin{gather*}
x=F(u+w_1+w_2),
\\
w_1 \in \Ker\left(D_uF\right) \cap \Ker\left(D_uG\right)
\\
\tag*{and}
\|w_1\|<K \sqrt{|x-F(u)|}, \quad \|w_2\|<K |x-F(u)|.
\end{gather*}
\end{theorem}

\label{11jan1}
There are a vector space $W\subset X$ of dimension $D$ and a vector space $V\subset W$ of dimension $N-r$ such that the restriction $\tilde{F}:W_{\bar{u}} \to \R^N$ of $F$ to $W_{\bar{u}} := \{\bar{u}\} + W$ satisfies the following properties: There holds
